            .iter()
            .any(|m| m.contains("ci_step") && m.contains("echo ci")));
        assert!(!ui
            .messages()
            .iter()
            .any(|m| m.contains("ci_step") && m.contains("skipped")));
    }

    #[test]
    fn list_shows_workflow_with_arrows() {
