extends:
  - url: "https://example.com/base-config.yml"
"#;
        let config: BivvyConfig = serde_yaml::from_str(yaml).unwrap();
        assert!(config.extends.is_some());
        assert_eq!(config.extends.as_ref().unwrap().len(), 1);
    }

    #[test]
    fn parses_secrets_config() {
        let yaml = r#"
