/// Known top-level keys in BivvyConfig.
///
/// Used to detect typos and invalid field names that would otherwise
/// be silently ignored due to `#[serde(default)]`.
const KNOWN_CONFIG_KEYS: &[&str] = &[
    "app_name",
    "settings",
    "template_sources",
    "steps",
    "workflows",
    "secrets",
    "extends",
    "requirements",
    "vars",
];

/// Validate that a YAML value contains no unknown top-level keys.
///
/// Because `BivvyConfig` uses `#[serde(default)]`, unknown keys are
/// silently ignored during deserialization, causing the config to
/// fall back to defaults without warning. This function catches that.
///
/// # Errors
///
/// Returns `ConfigParseError` listing unrecognized keys.
fn validate_known_keys(value: &serde_yaml::Value, source_path: &Path) -> Result<()> {
    if let serde_yaml::Value::Mapping(map) = value {
        let unknown_keys: Vec<String> = map
            .keys()
            .filter_map(|k| k.as_str())
            .filter(|k| !KNOWN_CONFIG_KEYS.contains(k))
            .map(String::from)
            .collect();

        if !unknown_keys.is_empty() {
            return Err(BivvyError::ConfigParseError {
                path: source_path.to_path_buf(),
                message: format!(
                    "unknown config keys: {}. Valid top-level keys are: {}",
                    unknown_keys.join(", "),
                    KNOWN_CONFIG_KEYS.join(", ")
                ),
            });
        }
    }
    Ok(())
}

