        let config = load_config(temp.path(), Some(&override_path)).unwrap();
        assert_eq!(config.app_name, Some("CustomApp".to_string()));
    }

    #[test]
    fn load_merged_config_preserves_step_definitions() {
        let temp = TempDir::new().unwrap();
