        let content = "name: MyApp\nsteps:\n  hello:\n    command: echo hello";
        let result = parse_config(content, Path::new("test.yml"));

        assert!(matches!(result, Err(BivvyError::ConfigParseError { .. })));
        if let Err(BivvyError::ConfigParseError { message, .. }) = result {
            assert!(message.contains("name"), "should mention the unknown key 'name'");
            assert!(message.contains("unknown config keys"), "should describe the problem");
        }
    }

    #[test]
    fn parse_config_accepts_all_valid_keys() {
        let content = r#"
app_name: TestApp
settings:
  default_output: verbose
steps:
  test:
    command: echo test
workflows:
  default:
    steps: [test]
vars:
  greeting: hello
"#;
        let result = parse_config(content, Path::new("test.yml"));
        assert!(result.is_ok());
    }

